const integer = (value, min, max) => Number.isSafeInteger(value) && Number(value) >= min && Number(value) <= max;
const text = (value, min, max) => typeof value === "string" && value.length >= min && value.length <= max;
const timestamp = (value) => typeof value === "string" && /^\d{4}-\d\d-\d\dT.*(?:Z|[+-]\d\d:\d\d)$/.test(value) && Number.isFinite(Date.parse(value));
const orderId = (value) => typeof value === "string" && /^[0-9]{1,30}$/.test(value);
const fingerprint = (value) => typeof value === "string" && /^[a-f0-9]{64}$/.test(value);
// Missing/invalid raw Shopify revision is a cache miss, never a synthesized paid revision.
