        !Array.isArray(value.jobTypes) || value.jobTypes.length !== 1 || value.jobTypes[0] !== "RECONCILE" ||
        (value.leaseSeconds !== undefined && !integer(value.leaseSeconds, 30, 600)) ||
        !Array.isArray(value.candidates) || value.candidates.length > 201)
        return false;
    const seen = new Set();
    let handoffs = 0;
    let legacy = 0;
    for (const candidate of value.candidates) {
        if (!object(candidate) || !["handoff", "legacy_due"].includes(String(candidate.origin)) || !orderId(candidate.shopifyOrderId) ||
            typeof candidate.shopifyOrderName !== "string" || !/^#NEONT[0-9]+$/.test(candidate.shopifyOrderName))
            return false;
        const key = `${candidate.origin}:${candidate.shopifyOrderId}`;
        if (seen.has(key))
            return false;
        seen.add(key);
        if (candidate.origin === "handoff")
            handoffs += 1;
        else {
            legacy += 1;
            if (!timestamp(candidate.firstSeenAt) || !timestamp(candidate.nextAttemptAt) || !integer(candidate.lockedUntil, 0, Number.MAX_SAFE_INTEGER))
                return false;
        }
        if (candidate.amountCents != null && !integer(candidate.amountCents, 0, 999_999_999_999_999))
            return false;
        if (candidate.currency != null && candidate.currency !== "EUR")
            return false;
        if (candidate.sourceEventId != null && !text(candidate.sourceEventId, 1, 300))
            return false;
        if (candidate.sourceRevision != null && (!object(candidate.sourceRevision) || JSON.stringify(candidate.sourceRevision).length > 2000))
            return false;
